    /// default) or over it. Null without RTGBC_VIDEO, when its layers are all
    /// taken, or for a picture whose colours the plane cannot make.
    pub fn OpenVideoLayer(self: *RtgBase, board: *rtg.RtgBoard, tag_list: ?[*]const utility.TagItem) ?*rtg.RtgVideoLayer {
        return libraries.call(self, LVO.OpenVideoLayer, Fn.OpenVideoLayer, .{ board, tag_list });
    }

    /// Give a layer back: nothing shown on it from the next frame. Null does
    /// nothing.
    pub fn CloseVideoLayer(self: *RtgBase, layer: ?*rtg.RtgVideoLayer) void {
        return libraries.call(self, LVO.CloseVideoLayer, Fn.CloseVideoLayer, .{layer});
    }

    /// Show `src` of a picture on the layer from the next frame, scaled into
    /// its place; returns once the controller has taken it, so the picture
    /// shown before may be given back. Null shows nothing. A picture needs
    /// its part. RTGERR_BAD_ARG for one the plane cannot read or scale.
    pub fn ShowVideoFrame(self: *RtgBase, layer: *rtg.RtgVideoLayer, picture: ?*const rtg.RtgYuv, src: ?*const rtg.RtgRect) i32 {
        return libraries.call(self, LVO.ShowVideoFrame, Fn.ShowVideoFrame, .{ layer, picture, src });
    }

    /// The layer's place, in the display's coordinates, from the next frame;
    /// an empty rectangle hides it.
    pub fn MoveVideoLayer(self: *RtgBase, layer: *rtg.RtgVideoLayer, place: *const rtg.RtgRect) i32 {
        return libraries.call(self, LVO.MoveVideoLayer, Fn.MoveVideoLayer, .{ layer, place });
    }

    /// Bits a pixel of that format takes; 0 for a format this build does not
    /// know.
    pub fn RtgFormatBits(self: *RtgBase, format: u32) u32 {
        return libraries.call(self, LVO.RtgFormatBits, Fn.RtgFormatBits, .{format});
    }

    /// Bytes a row of `width` pixels of that format needs, before any rounding
    /// a board asks for; 0 for a format not known.
    pub fn RtgRowBytes(self: *RtgBase, format: u32, width: u32) u32 {
        return libraries.call(self, LVO.RtgRowBytes, Fn.RtgRowBytes, .{ format, width });
    }

    /// One of H.273's numbers as rtg says it: `kind` is the table it is of
    /// (RTGCICP_MATRIX, RTGCICP_TRANSFER, RTGCICP_PRIMARIES). Below zero
    /// where the number says nothing, or names what no board here shows.
    pub fn RtgCicp(self: *RtgBase, kind: u32, value: u32) i32 {
        return libraries.call(self, LVO.RtgCicp, Fn.RtgCicp, .{ kind, value });
    }

    /// Offer every device no driver has to the drivers on the list: a panel of
    /// the board's list, a display function on PCI. The driver that takes one
    /// makes a board for each of its outputs. Answers how many boards were
    /// made. graphics.library calls it as the machine starts. Not from
    /// interrupts.
    pub fn BindRtgDrivers(self: *RtgBase) u32 {
        return libraries.call(self, LVO.BindRtgDrivers, Fn.BindRtgDrivers, .{});
    }

    /// Copy out up to `count` of the drivers on the list, highest priority
    /// first; answers how many there are. Null and 0 ask for the number alone.
    pub fn GetRtgDrivers(self: *RtgBase, into: ?[*]rtg.RtgDriverInfo, count: u32) u32 {
        return libraries.call(self, LVO.GetRtgDrivers, Fn.GetRtgDrivers, .{ into, count });
    }

    /// The same for the devices, in the order they were found.
    pub fn GetRtgDevices(self: *RtgBase, into: ?[*]rtg.RtgDeviceInfo, count: u32) u32 {
        return libraries.call(self, LVO.GetRtgDevices, Fn.GetRtgDevices, .{ into, count });
    }

    /// Copy out up to `count` of the board's modes, the largest picture
    /// first; answers how many there are. Null and 0 ask for the number
    /// alone.
    pub fn GetBoardModes(self: *RtgBase, board: *rtg.RtgBoard, into: ?[*]rtg.RtgMode, count: u32) u32 {
        return libraries.call(self, LVO.GetBoardModes, Fn.GetBoardModes, .{ board, into, count });
    }

    /// The number of the board's mode nearest a wish - that size if it has
    /// it, else the smallest that holds it, else its largest - and what it is,
    /// into `mode`. RTG_ANY leaves a figure open. Never 0 on a board that has
    /// a mode: on a display of one mode always that mode, and the caller
    /// compares what it asked for with what came back.
    pub fn BestBoardMode(self: *RtgBase, board: *rtg.RtgBoard, width: u32, height: u32, refresh_mhz: u32, format: u32, mode: ?*rtg.RtgMode) u32 {
        return libraries.call(self, LVO.BestBoardMode, Fn.BestBoardMode, .{ board, width, height, refresh_mhz, format, mode });
    }

    /// What is on the board's connector, into `info`, of which `size` bytes
    /// are there - pass @sizeOf(RtgMonitorInfo). Returns the bytes written.
    /// A panel is a monitor that is always there.
    pub fn GetBoardMonitor(self: *RtgBase, board: *rtg.RtgBoard, info: *rtg.RtgMonitorInfo, size: u32) u32 {
        return libraries.call(self, LVO.GetBoardMonitor, Fn.GetBoardMonitor, .{ board, info, size });
    }

    /// Copy out the EDID of the monitor on the board, up to `size` bytes;
    /// answers its length, 0 for none. Null and 0 ask for the length alone.
    pub fn ReadBoardEDID(self: *RtgBase, board: *rtg.RtgBoard, buffer: ?[*]u8, size: u32) u32 {
        return libraries.call(self, LVO.ReadBoardEDID, Fn.ReadBoardEDID, .{ board, buffer, size });
    }

    /// Have `task` signalled with `signals` whenever something about the
    /// boards changed: a board made or gone, a monitor come or gone, a list
    /// of modes made again, a mode set. The task then reads the boards, and
    /// each board's `changes`. Null without memory, or for no signals.
    pub fn AddRtgNotify(self: *RtgBase, task: *exec.Task, signals: u32) ?*rtg.RtgNotify {
        return libraries.call(self, LVO.AddRtgNotify, Fn.AddRtgNotify, .{ task, signals });
    }

    /// Give a notification back. Null does nothing.
    pub fn RemRtgNotify(self: *RtgBase, notify: ?*rtg.RtgNotify) void {
        return libraries.call(self, LVO.RemRtgNotify, Fn.RemRtgNotify, .{notify});
    }
};
